"""CALM implementation of :class:`A2AEngineAdapter`.

Flows, the domain, and ``include_conversation_repair`` stay here. The shared
executor does not import them.
"""

from __future__ import annotations

from typing import TYPE_CHECKING, Any

import structlog
from a2a.server.tasks.task_updater import TaskUpdater
from a2a.types import AgentSkill, Message

from rasa.core.a2a_server.agent_card_generator import AgentCardGenerator
from rasa.core.a2a_server.config import (
    A2AServerSettings,
    validate_a2a_server_session_config_or_raise,
)
from rasa.core.a2a_server.engine_adapter import EngineCancelResult, PreparedA2AInput
from rasa.core.a2a_server.message_adapter import A2AMessageAdapter
from rasa.core.a2a_server.orchestrator_cancel import OrchestratorCancelTurn
from rasa.core.a2a_server.task_state_mapper import (
    TaskStateMapper,
    TaskStateMappingResult,
)
from rasa.core.a2a_server.task_status_payload import build_final_status_message
from rasa.core.constants import A2A_CLIENT_SLOT_COMMANDS_METADATA_KEY
from rasa.shared.core.domain import Domain
from rasa.shared.engine_version import CALM_ENGINE_VERSION
from rasa.shared.exceptions import RasaException

if TYPE_CHECKING:
    from a2a.types import Message as A2AMessage

    from rasa.core.a2a_server.a2a_output_channel import A2AOutputChannel
    from rasa.core.agent import Agent
    from rasa.core.processor import MessageProcessor
    from rasa.shared.core.flows import FlowsList
    from rasa.shared.core.trackers import DialogueStateTracker

structlogger = structlog.get_logger()


class CalmA2AEngineAdapter:
    """CALM flows, slots, and conversation repair behind the A2A port."""

    def __init__(
        self,
        agent: "Agent | None" = None,
        *,
        include_conversation_repair: bool = True,
        flows: "FlowsList | None" = None,
    ) -> None:
        """Bind a loaded CALM agent.

        ``flows`` is set when a caller already loaded them (the output channel
        tests). Otherwise each call that needs flows loads them from the agent.
        """
        self._agent = agent
        self.include_conversation_repair = include_conversation_repair
        self._flows = flows

    async def get_card_skills(self) -> list[AgentSkill]:
        """Advertise CALM flows, including repair patterns when the flag is on."""
        flows = await self._flows_for_turn()
        if flows is None:
            raise RasaException(
                "Cannot build A2A card skills: the CALM agent model is not loaded."
            )
        return AgentCardGenerator.skills_from_flows(
            flows, include_conversation_repair=self.include_conversation_repair
        )

    def pattern_replies_are_user_facing(self) -> bool:
        """Repair on means pattern utterances are ordinary replies."""
        return self.include_conversation_repair

    def prepare_input(
        self,
        message: "A2AMessage | None",
        text: str,
        metadata: dict[str, Any],
    ) -> PreparedA2AInput:
        """Map orchestrator slot payloads to ``SetSlot`` commands."""
        user_metadata = dict(metadata) if metadata else {}
        domain = self._agent.domain if self._agent is not None else None
        if not isinstance(domain, Domain):
            structlogger.debug(
                "a2a_server.rasa_a2a_agent_executor.domain_not_loaded.skip_set_slot_prefilling"
            )
            return PreparedA2AInput(text=text, metadata=user_metadata)

        message_adapter = A2AMessageAdapter(domain)
        slot_values = message_adapter.extract_slot_values(message, text, user_metadata)
        text = message_adapter.strip_slot_markers_from_text(text)
        commands = message_adapter.to_set_slot_commands(slot_values)
        user_metadata.pop("slots", None)
        if commands:
            user_metadata[A2A_CLIENT_SLOT_COMMANDS_METADATA_KEY] = [
                command.as_dict() for command in commands
            ]
        return PreparedA2AInput(text=text, metadata=user_metadata)

    def map_task_state(
        self,
        tracker: "DialogueStateTracker",
        *,
        outcome: Any | None = None,
        orchestrator_cancel: bool = False,
    ) -> TaskStateMappingResult:
        """Map the CALM tracker to an A2A task state.

        CALM reads the stack, not the Mantle ``TurnResult``. Orchestrator
        cancel still comes from the cancel-pattern frame the dialogue apply
        pushes.
        """
        del outcome, orchestrator_cancel
        return TaskStateMapper().map(
            tracker,
            include_conversation_repair=self.include_conversation_repair,
        )

    def uses_latest_action_for_turn_end(self) -> bool:
        """Close a leftover ``working`` state from ``action_listen``."""
        return True

    async def build_status_data(
        self,
        mapping: TaskStateMappingResult,
        tracker: "DialogueStateTracker | None",
        *,
        updater: TaskUpdater,
        user_visible_text: str | None = None,
        conversation_repair_agent_utterances: list[str] | None = None,
    ) -> Message | None:
        """Build the CALM status payload, including flow slot data.

        Flows are loaded here, when the status is sent, not at the start of
        the turn.
        """
        return build_final_status_message(
            mapping,
            tracker,
            updater,
            flows=await self._flows_for_turn(),
            user_visible_text=user_visible_text,
            conversation_repair_agent_utterances=conversation_repair_agent_utterances,
        )

    async def cancel_active_work(
        self,
        sender_id: str,
        output_channel: "A2AOutputChannel",
    ) -> EngineCancelResult:
        """Run ``pattern_cancel`` and publish the terminal canceled state."""
        if self._agent is None:
            raise RasaException(
                "Cannot cancel the A2A task: the CALM agent is not loaded."
            )
        await OrchestratorCancelTurn.run(
            self._agent,
            sender_id,
            output_channel,
            flows=self._flows,
        )
        return EngineCancelResult()

    def validate_startup(
        self,
        settings: A2AServerSettings,
        processor: "MessageProcessor",
    ) -> None:
        """Require the domain session config to resume an A2A context."""
        validate_a2a_server_session_config_or_raise(
            settings,
            processor.session_config,
            engine_version=CALM_ENGINE_VERSION,
        )

    async def _flows_for_turn(self) -> "FlowsList | None":
        if self._flows is not None:
            return self._flows
        agent = self._agent
        processor = agent.processor if agent is not None else None
        if processor is None:
            return None
        return await processor.get_flows()
